/**
 * Session pricing (docs/PLAN.md §4). Pure TypeScript with relative imports only, so the
 * server can run the exact same code for the final bill (Phase 4).
 *
 * 1. A session is a list of segments (a new one starts when the player count changes or
 *    the group moves to another station).
 * 2. Each segment is cut again wherever the matching rate could change: local midnight and
 *    every rule's start/end time.
 * 3. Each piece is charged by the matching rate rule with the highest priority
 *    (ties: the more specific rule, then the rule id, so the result never depends on order).
 * 4. Charge = minutes × price per hour / 60, rounded to the piaster per bill line.
 * 5. A package's fixed price covers its first N minutes; time after that is charged as above.
 * 6. Snacks are added and the discount subtracted to give the total.
 */
import { chargeForMinutes, type Piasters } from './money.ts';
import {
  dateKey,
  fromLocal,
  localInstants,
  MINUTE_MS,
  MINUTES_PER_DAY,
  minuteOfDay,
  offsetAt,
  previousDateKey,
  toLocal,
} from './zoned-time.ts';

export const ALL_DAYS = 0b1111111;

export type RateRule = {
  id: string;
  stationTypeId: string;
  name?: string | null;
  pricePerHour: Piasters;
  playersMin?: number | null;
  playersMax?: number | null;
  /** Bit 0 = Sunday ... bit 6 = Saturday. */
  daysOfWeek: number;
  /** Minutes after local midnight. Both null = all day. toMinute <= fromMinute crosses midnight. */
  fromMinute?: number | null;
  toMinute?: number | null;
  priority: number;
  /** Local dates "YYYY-MM-DD", both inclusive. */
  validFrom?: string | null;
  validTo?: string | null;
};

export type HourPackage = { id: string; name: string; minutes: number; price: Piasters };

export type Segment = {
  /** UTC epoch milliseconds. */
  start: number;
  end: number;
  players: number;
  stationTypeId: string;
};

export type BillItem = { quantity: number; unitPrice: Piasters };

export type Discount = { type: 'amount'; amount: Piasters } | { type: 'percent'; percent: number };

export type TimeLine = {
  segmentIndex: number;
  start: number;
  end: number;
  minutes: number;
  players: number;
  stationTypeId: string;
  /** null: covered by the package, or no rate rule matched (see `uncovered`). */
  ruleId: string | null;
  ruleName: string | null;
  pricePerHour: Piasters;
  coveredByPackage: boolean;
  amount: Piasters;
};

export type Bill = {
  lines: TimeLine[];
  package: HourPackage | null;
  totalMinutes: number;
  /** Package price + all time lines. */
  timeAmount: Piasters;
  itemsAmount: Piasters;
  discountAmount: Piasters;
  total: Piasters;
  /** Lines with no matching rate rule (charged 0). The bill is incomplete if this is not empty. */
  uncovered: TimeLine[];
};

export type PricingInput = {
  segments: Segment[];
  rules: RateRule[];
  timeZone: string;
  package?: HourPackage | null;
  items?: BillItem[];
  discount?: Discount | null;
};

export function isDayInMask(mask: number, weekday: number): boolean {
  return (mask & (1 << weekday)) !== 0;
}

export function daysToMask(days: readonly number[]): number {
  return days.reduce((mask, d) => mask | (1 << d), 0);
}

export function maskToDays(mask: number): number[] {
  return [0, 1, 2, 3, 4, 5, 6].filter((d) => isDayInMask(mask, d));
}

function hasWindow(rule: RateRule): rule is RateRule & { fromMinute: number; toMinute: number } {
  return rule.fromMinute != null && rule.toMinute != null;
}

/** How many conditions a rule has; breaks priority ties in favour of the more specific rule. */
export function specificity(rule: RateRule): number {
  return (
    Number(rule.playersMin != null || rule.playersMax != null) +
    Number(hasWindow(rule)) +
    Number(rule.daysOfWeek !== ALL_DAYS) +
    Number(rule.validFrom != null || rule.validTo != null)
  );
}

function compareRules(a: RateRule, b: RateRule): number {
  return (
    b.priority - a.priority ||
    specificity(b) - specificity(a) ||
    (a.id < b.id ? -1 : a.id > b.id ? 1 : 0)
  );
}

function validOn(rule: RateRule, date: string): boolean {
  return (
    (rule.validFrom == null || date >= rule.validFrom) &&
    (rule.validTo == null || date <= rule.validTo)
  );
}

export type LocalMoment = {
  /** 0 = Sunday. */
  weekday: number;
  /** Minutes after local midnight (may have a fraction). */
  minute: number;
  /** "YYYY-MM-DD" */
  date: string;
};

/** Does `rule` apply at this local moment? Windows crossing midnight belong to the day they start. */
export function ruleApplies(
  rule: RateRule,
  stationTypeId: string,
  players: number,
  at: LocalMoment,
): boolean {
  if (rule.stationTypeId !== stationTypeId) return false;
  if (rule.playersMin != null && players < rule.playersMin) return false;
  if (rule.playersMax != null && players > rule.playersMax) return false;

  const today = isDayInMask(rule.daysOfWeek, at.weekday) && validOn(rule, at.date);
  if (!hasWindow(rule)) return today;

  const { fromMinute: from, toMinute: to } = rule;
  if (from < to) return today && at.minute >= from && at.minute < to;
  // Crosses midnight: the evening part belongs to today, the early-morning part to yesterday.
  if (at.minute >= from) return today;
  if (at.minute < to) {
    const yesterday = (at.weekday + 6) % 7;
    return isDayInMask(rule.daysOfWeek, yesterday) && validOn(rule, previousDateKey(at.date));
  }
  return false;
}

/** The rule that prices this moment, or null if none matches. */
export function findRule(
  rules: readonly RateRule[],
  stationTypeId: string,
  players: number,
  at: LocalMoment,
): RateRule | null {
  let best: RateRule | null = null;
  for (const rule of rules) {
    if (ruleApplies(rule, stationTypeId, players, at) && (!best || compareRules(rule, best) < 0)) {
      best = rule;
    }
  }
  return best;
}

/** Local times of day (minutes) where the price may change: midnight and every rule edge. */
function boundaryMinutes(rules: readonly RateRule[]): number[] {
  const set = new Set<number>([0, MINUTES_PER_DAY]);
  for (const rule of rules) {
    if (hasWindow(rule)) {
      set.add(rule.fromMinute);
      set.add(rule.toMinute);
    }
  }
  return [...set].sort((a, b) => a - b);
}

type Piece = Omit<TimeLine, 'amount' | 'minutes'>;

/**
 * If the UTC offset changes (DST) between `from` and `to`, the instant it changes; else `to`.
 * The wall clock jumps there, so the matching rule must be looked up again.
 */
function clockChangeBefore(from: number, to: number, timeZone: string): number {
  const offset = offsetAt(from, timeZone);
  if (offsetAt(to - 1, timeZone) === offset) return to;
  let lo = from; // same offset as `from`
  let hi = to - 1; // different offset
  while (hi - lo > 1) {
    const mid = Math.floor((lo + hi) / 2);
    if (offsetAt(mid, timeZone) === offset) lo = mid;
    else hi = mid;
  }
  return hi;
}

/** Cut [start, end) at every local boundary and price each piece. */
function pricePieces(
  segment: Segment,
  segmentIndex: number,
  rules: readonly RateRule[],
  timeZone: string,
): Piece[] {
  const typeRules = rules.filter((r) => r.stationTypeId === segment.stationTypeId);
  const edges = boundaryMinutes(typeRules);
  const pieces: Piece[] = [];
  let t = segment.start;
  while (t < segment.end) {
    const local = toLocal(t, timeZone);
    const at: LocalMoment = {
      weekday: local.weekday,
      minute: minuteOfDay(local),
      date: dateKey(local),
    };
    const nextEdge = edges.find((m) => m > at.minute) ?? MINUTES_PER_DAY;
    // When clocks go back the edge's wall time can happen twice: take the first one after t.
    const boundary =
      localInstants(timeZone, local.year, local.month, local.day, 0, nextEdge).find((i) => i > t) ??
      Math.max(fromLocal(timeZone, local.year, local.month, local.day, 0, nextEdge), t + MINUTE_MS);
    const end = clockChangeBefore(t, Math.min(segment.end, boundary), timeZone);
    const rule = findRule(typeRules, segment.stationTypeId, segment.players, at);
    pieces.push({
      segmentIndex,
      start: t,
      end,
      players: segment.players,
      stationTypeId: segment.stationTypeId,
      ruleId: rule?.id ?? null,
      ruleName: rule?.name ?? null,
      pricePerHour: rule?.pricePerHour ?? 0,
      coveredByPackage: false,
    });
    t = end;
  }
  return pieces;
}

/** Mark the first `minutes` of the session as covered by the package (splitting a piece if needed). */
function applyPackage(pieces: Piece[], minutes: number): Piece[] {
  let remaining = minutes * MINUTE_MS;
  const out: Piece[] = [];
  for (const piece of pieces) {
    const length = piece.end - piece.start;
    if (remaining <= 0) {
      out.push(piece);
    } else if (length <= remaining) {
      out.push({ ...piece, coveredByPackage: true });
      remaining -= length;
    } else {
      const split = piece.start + remaining;
      out.push({ ...piece, end: split, coveredByPackage: true });
      out.push({ ...piece, start: split });
      remaining = 0;
    }
  }
  return out;
}

/** Join neighbouring pieces billed the same way (e.g. a base rate cut at midnight). */
function merge(pieces: Piece[]): Piece[] {
  const out: Piece[] = [];
  for (const piece of pieces) {
    const last = out[out.length - 1];
    if (
      last &&
      last.end === piece.start &&
      last.segmentIndex === piece.segmentIndex &&
      last.coveredByPackage === piece.coveredByPackage &&
      (piece.coveredByPackage || last.ruleId === piece.ruleId)
    ) {
      out[out.length - 1] = { ...last, end: piece.end };
    } else {
      out.push(piece);
    }
  }
  return out;
}

export function discountAmount(
  subtotal: Piasters,
  discount: Discount | null | undefined,
): Piasters {
  if (!discount) return 0;
  const raw =
    discount.type === 'amount'
      ? discount.amount
      : Math.round((subtotal * Math.min(100, Math.max(0, discount.percent))) / 100);
  return Math.min(subtotal, Math.max(0, raw));
}

/** Price a whole session. Throws RangeError on invalid segments. */
export function priceSession(input: PricingInput): Bill {
  const { segments, rules, timeZone } = input;
  const pkg = input.package ?? null;

  let pieces: Piece[] = [];
  segments.forEach((segment, index) => {
    if (!Number.isFinite(segment.start) || !Number.isFinite(segment.end)) {
      throw new RangeError('Segment times must be numbers');
    }
    if (segment.end < segment.start) throw new RangeError('A segment cannot end before it starts');
    if (!Number.isInteger(segment.players) || segment.players < 1) {
      throw new RangeError('Players must be a whole number >= 1');
    }
    pieces.push(...pricePieces(segment, index, rules, timeZone));
  });
  if (pkg) pieces = applyPackage(pieces, pkg.minutes);

  const lines: TimeLine[] = merge(pieces).map((piece) => {
    const minutes = (piece.end - piece.start) / MINUTE_MS;
    return {
      ...piece,
      ...(piece.coveredByPackage ? { ruleId: null, ruleName: null, pricePerHour: 0 } : {}),
      minutes,
      amount: piece.coveredByPackage ? 0 : chargeForMinutes(minutes, piece.pricePerHour),
    };
  });

  const timeAmount = (pkg?.price ?? 0) + lines.reduce((sum, l) => sum + l.amount, 0);
  const itemsAmount = (input.items ?? []).reduce((sum, i) => sum + i.quantity * i.unitPrice, 0);
  const subtotal = timeAmount + itemsAmount;
  const discount = discountAmount(subtotal, input.discount);

  return {
    lines,
    package: pkg,
    totalMinutes: lines.reduce((sum, l) => sum + l.minutes, 0),
    timeAmount,
    itemsAmount,
    discountAmount: discount,
    total: subtotal - discount,
    uncovered: lines.filter((l) => !l.coveredByPackage && l.ruleId === null),
  };
}
